<?php
namespace App\Livewire\LMS\AssessmentComponents;
use App\Models\{AssessmentComponent,School,Term}; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Illuminate\Validation\{Rule,ValidationException}; use Jantinnerezo\LivewireAlert\Facades\LivewireAlert; use Livewire\Attributes\Layout; use Livewire\Component; use Livewire\WithPagination; use Throwable;
#[Layout('layouts.lms')]
class Index extends Component { use AuthorizesRequests; use WithPagination; public bool $showFormModal=false,$showDeleteModal=false; public ?int $editingId=null,$deletingId=null; public string $termId='',$name='',$weight='',$sequence='0';
public function mount():void{$this->authorize('viewAny',AssessmentComponent::class);} public function create():void{$this->authorize('create',AssessmentComponent::class);$this->resetForm();$this->showFormModal=true;} public function edit(AssessmentComponent $component):void{$this->authorize('update',$component);$this->editingId=$component->id;$this->termId=(string)$component->term_id;$this->name=$component->name;$this->weight=(string)$component->weight;$this->sequence=(string)$component->sequence;$this->showFormModal=true;}
public function save():void{$component=$this->editingId?AssessmentComponent::findOrFail($this->editingId):null;$this->authorize($component?'update':'create',$component??AssessmentComponent::class);try{$data=$this->validate(['termId'=>['required','integer',Rule::exists('terms','id')],'name'=>['required','string','max:100'],'weight'=>['required','numeric','min:.01','max:100'],'sequence'=>['required','integer','min:0']]);$term=Term::with('academicYear')->findOrFail($data['termId']);abort_unless($term->academicYear->school_id===School::query()->value('id'),422,'Choose a term belonging to this school.');$total=AssessmentComponent::where('term_id',$term->id)->when($component,fn($q)=>$q->whereKeyNot($component->id))->sum('weight')+(float)$data['weight'];if($total>100){$this->addError('weight','Component weights cannot exceed 100% for this term.');return;}AssessmentComponent::updateOrCreate(['id'=>$component?->id],['term_id'=>$term->id,'name'=>$data['name'],'weight'=>$data['weight'],'sequence'=>$data['sequence']]);$this->showFormModal=false;$this->resetForm();LivewireAlert::title($component?'Component updated':'Component added')->success()->asToast()->position('top-end')->show();}catch(ValidationException $e){LivewireAlert::title('Check the form')->error()->asToast()->position('top-end')->show();throw $e;}catch(Throwable $e){report($e);LivewireAlert::title('Unable to save component')->error()->asToast()->position('top-end')->show();}}
public function confirmDelete(AssessmentComponent $component):void{$this->authorize('delete',$component);$this->deletingId=$component->id;$this->showDeleteModal=true;} public function delete():void{$component=AssessmentComponent::findOrFail($this->deletingId);$this->authorize('delete',$component);try{$component->delete();$this->showDeleteModal=false;$this->deletingId=null;LivewireAlert::title('Component deleted')->success()->asToast()->position('top-end')->show();}catch(Throwable $e){report($e);LivewireAlert::title('Unable to delete component')->error()->asToast()->position('top-end')->show();}} public function closeModals():void{$this->showFormModal=false;$this->showDeleteModal=false;$this->resetForm();$this->resetErrorBag();} private function resetForm():void{$this->reset(['editingId','deletingId','termId','name','weight','sequence']);$this->sequence='0';$this->resetValidation();} public function render(){$schoolId=School::query()->value('id');$terms=Term::with('academicYear')->whereHas('academicYear',fn($q)=>$q->where('school_id',$schoolId))->orderBy('sequence')->get();return view('livewire.lms.assessment-components.index',['components'=>AssessmentComponent::with('term')->whereIn('term_id',$terms->pluck('id'))->orderBy('sequence')->paginate(15),'terms'=>$terms]);}}
